echo ""
echo "Testing OCR using data collected by IMU"
ID="hello$RANDOM"
WORD=HELLO
# Prints x for one letter: a single continuous stroke in the X-Z plane
# (X right, Z up, metres), as x,y,z triples.
traj() {
python3 - "$1" <<'PY'
import sys, math
W, H = 0.07, 0.10

def poly(pts, step=0.01):
    out = [pts[0]]
    for (x0, z0), (x1, z1) in zip(pts, pts[1:]):
        n = max(1, int(math.hypot(x1 - x0, z1 - z0) / step))
        out += [(x0 + (x1 - x0) * i / n, z0 + (z1 - z0) * i / n) for i in range(1, n + 1)]
    return out

letters = {
    "H": poly([(0, 0), (0, H), (0, H / 2), (W, H / 2), (W, H), (W, 0)]),
    "E": poly([(W, H), (0, H), (0, H / 2), (0.8 * W, H / 2), (0, H / 2), (0, 0), (W, 0)]),
    "L": poly([(0, H), (0, 0), (W, 0)]),
    "O": [(W / 2 + W / 2 * math.cos(2 * math.pi * i / 40),
           H / 2 + H / 2 * math.sin(2 * math.pi * i / 40)) for i in range(41)],
}
print(",".join("%.4f,%.4f,0.0000" % (x, z) for x, z in letters[sys.argv[1]]))
PY
}

for i in 0 1 2 3 4; do
  X=$(traj "${WORD:$i:1}")
  echo "packet $i (${WORD:$i:1}):"
  curl -s -X POST "$HOST_URL/api/v1/air_writing" \
    -H "Content-Type: application/json" \
    -d "{\"request_id\":\"$ID\",\"packet_index\":$i,\"total_packets\":5,\"x\":\"$X\"}"
  echo
  sleep 0.5
done

